"""Public and dashboard addresses for links generated by the backend."""
from urllib.parse import urlsplit

from config import CONFIG


def frontend_origins() -> tuple[str, str]:
    url = urlsplit(CONFIG.FRONTEND_URL)
    host = (url.hostname or '').removeprefix('app.')
    port = f':{url.port}' if url.port else ''
    site = f'{url.scheme}://{host}{port}'
    app = site if host.endswith('.vercel.app') else f'{url.scheme}://app.{host}{port}'
    return site, app


def dashboard_url(path: str = '/') -> str:
    site, app = frontend_origins()
    prefix = '/app' if site == app else ''
    return f'{app}{prefix}/{path.lstrip("/")}'
